import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n], b = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        for (int i = 0; i < n; i++) b[i] = nextLong();
        long[] suffix = new long[n]; // suffix[i] = max(b[i..n-1])
        suffix[n - 1] = b[n - 1];
        for (int i = n - 2; i >= 0; i--) suffix[i] = Math.max(b[i], suffix[i + 1]);
        long prefix = a[0], answer = Long.MAX_VALUE;
        // the path moves down at exactly one column i
        for (int i = 0; i < n; i++) {
            prefix = Math.max(prefix, a[i]);
            answer = Math.min(answer, Math.max(prefix, suffix[i]));
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"math"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	b := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	for i := range b {
		b[i] = nextInt()
	}
	suffix := make([]int64, n) // suffix[i] = max(b[i..n-1])
	suffix[n-1] = b[n-1]
	for i := n - 2; i >= 0; i-- {
		suffix[i] = max(b[i], suffix[i+1])
	}
	prefix, answer := a[0], int64(math.MaxInt64)
	// the path moves down at exactly one column i
	for i := 0; i < n; i++ {
		prefix = max(prefix, a[i])
		answer = min(answer, max(prefix, suffix[i]))
	}
	fmt.Println(answer)
}
